(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,470274,e=>{"use strict";var l=e.i(843476),i=e.i(811337);function n(e){let n={li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.useMDXComponents)(),...e.components},{AnketaCollapse:r,AnketaGroup:c,AnketaList:d,AnketaPoint:h,AnketaProse:j,Whisper:x}=n;return r||s("AnketaCollapse",!0),c||s("AnketaGroup",!0),d||s("AnketaList",!0),h||s("AnketaPoint",!0),j||s("AnketaProse",!0),x||s("Whisper",!0),(0,l.jsxs)(c,{children:[(0,l.jsx)(r,{title:"Общая информация",defaultOpen:!0,children:(0,l.jsxs)(d,{children:[(0,l.jsxs)(h,{title:"Имя персонажа [русс|англ]",children:[(0,l.jsx)(n.p,{children:(0,l.jsx)(n.strong,{children:"Кайл Блейк | Kyle Blake"})}),(0,l.jsxs)(n.ul,{children:["\n",(0,l.jsxs)(n.li,{children:[(0,l.jsx)(n.strong,{children:"Франсиско Игнасио де Ариас"})," — имя при рождении, которое он похоронил ещё при жизни;"]}),"\n",(0,l.jsxs)(n.li,{children:[(0,l.jsx)(n.strong,{children:"«Палач»"})," — впервые получил его, когда устроил резню в Картахене, и снова приобрел это прозвище в Энкраже из-за своей жестокости."]}),"\n"]})]}),(0,l.jsx)(h,{title:"Возраст",children:(0,l.jsxs)(n.ul,{children:["\n",(0,l.jsx)(n.li,{children:"прожитый на земле: 37 лет."}),"\n",(0,l.jsx)(n.li,{children:"дата рождения — 17.09.1798г. | смерти: 27.08.1836г."}),"\n",(0,l.jsx)(n.li,{children:"прожитый в Загробном мире как грешная душа: 182 года"}),"\n"]})}),(0,l.jsx)(h,{title:"Пол",children:(0,l.jsx)(n.p,{children:"Мужской"})}),(0,l.jsxs)(h,{title:"Раса",children:[(0,l.jsx)(n.p,{children:"Призрак Дикой Охоты."}),(0,l.jsxs)(n.ul,{children:["\n",(0,l.jsx)(n.li,{children:"Кайл никогда не спрашивает у своих жертв последнее слово, не выслушивает их последней просьбы, он лишь вырывает из них последний крик, и даже в этот миг им не докричаться до него — всё это Палач уже видел и слышал столько раз, что ни капли жалости в нем не осталось. Он выносит приговор преступникам всех сортов и мастей, собственноручно ставя печать смерти на их лица, заставляя платить кровью за кровь, оком за око. И все увиденное отпечатывается на его собственных глаза, вся кровь остается на его собственных руках. Но взор Палача не погаснет, а руки не опустятся, пока существуют те, кто обращаются с человеческой жизнью как с разменной монетой, кто позволяет себе творить беззаконие. Его первая охота началась, когда у него отняли практически все, что у него было, и с того самого момента он карает тех, кто строит себе богатство и процветание на костях невинных."}),"\n"]})]})]})}),(0,l.jsxs)(r,{title:"Психологический профиль",children:[(0,l.jsx)(r,{title:"Характер",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"Прежде всего Кайл очень ценит независимость и свободу. В то же время он не анархист — находясь на службе у Хранителя, Палач признает его власть и авторитет. Но вне поручений Хранителя он предпочитает быть предоставленным самому себе и не любит ограничивать себя никакими рамками и обязательствами. Кайл активно пользуется правом выходить за пределы бастионов, бродит по местам с огромной концентрацией проклятой энергии и осматривает там каждый камень, пока агрессивная среда не заставляет его вернуться. Так лидер Дикой Охоты тренирует свою способность всюду преследовать свою цель — отсюда и рождаются легенды о том, что Дикая Охота найдет тебя, где бы ты ни спрятался. Эти легенды Кайл очень любит и время от времени обсуждает с другими грешниками неправдоподобные слухи и рассказы о вожаке Дикой Охоты, окутывая эту персону ореолом мистики. На самом же деле никакой мистики нет — все дело в остром уме Кайла и внимательности к деталям, что делает его первоклассной ищейкой, способной найти даже то, что зарыто достаточно глубоко. Таким он вынужден быть из-за своей работы, а риски заставляют его продумывать все свои шаги наперед."}),(0,l.jsx)(n.p,{children:'Несмотря на то, что он привык путешествовать в гордом одиночестве, где "гордое" — это ключевое слово, и постоянно искать что-то новенькое, ему нравится и спокойная жизнь в компании с другими людьми, когда Палач внутри него спит. Находящиеся рядом с Кайлом грешники видят его немногословным, пессимистичным и угрюмым, апатичным и холодным. Все дело в том, что когда Палач уходит на отдых, его усталость проявляется и в Кайле внешне. Кайл не отделяет себя от грозного лидера Дикой Охоты, и после длительных патрулей, которые к тому же далеко не всегда проходят мирно, а в особенности после кровавой охоты он долго приходит в себя. Его чувства притупляются после пребывания в доспехах, когда Палач начисто избавляется от всех эмоций вообще, и в такие дни Кайл напоминает зомби, который выполняет некую программу, но даже не осознает, для чего. Он занимается привычными делами вроде обработки камней, сам почти не ходит никуда, кроме как за едой, максимум увязывается за кем-то тенью, сопровождая по пути, но выступает больше в роли ведомого.'}),(0,l.jsx)(n.p,{children:"Рядом с другими грешниками у Кайла наступает оттепель и к нему постепенно возвращаются эмоции, которые мужчина в себе заглушил. Возвращается и Палач, после чего Кайл снова становится собой — непредсказуемым, готовым на любую авантюру, в одиночку или с кем-то, но чаще в одиночку, потому что для Палача все грешники — балласт, который мешает ему, а то и вовсе тянет на дно. Только четырёх грешников Кайл готов всюду брать с собой, только им он может доверить свои планы и секреты. Это четверо самых близких его друзей, которые в Дикой Охоте называют себя в честь всадников Апокалипсиса."}),(0,l.jsx)(n.p,{children:'Еще одна постоянная черта характера Кайла, которая выдает в нем грех Уныния — склонность постоянно ставить себя в самые неудобные, стесненные, отягощающие условия, и стойко их выдерживать раз за разом. Мужчина специально нагружает себя работой для того, чтобы из-за завала дел не иметь возможности освободиться, погружается в беспросветный мрак для того, чтобы не видеть ничего позитивного и радостного. Быть мрачным и хмурым и всегда находить причину и дальше оставаться таким — это то, без чего не обходится жизнь Кайла. Не пытайтесь вытащить его из этого болота — он живет там уже давно и прекрасно обустроился. А встретив тех, кто живет иначе, Кайл сравнивает их условия со своими, и это доставляет ему удовольствие — "Не смешите меня этой ерундой, не видите, что ли, в каком я тут кромешном аду?"'}),(0,l.jsx)(n.p,{children:'В Дикой Охоте Кайл проявляет себя как лидер — очень строгий и авторитарный, не терпящий обсуждения его команд и приказов, требующий полной дисциплины и повиновения. Он обладает абсолютной властью над охотниками, прекрасно это осознает и не собирается делить ее ни с кем. Из-за этого те из охотников, кто его недолюбливает, считают его самодуром, но это верно лишь отчасти — Кайл частенько "строит" подчиненных, отчитывая их за ошибки, требует от них безупречной работы, но того же самого он требует и от себя и даже больше, потому что лидер по его мнению должен не только не отставать от остальных, но даже опережать их, показывая пример. Кайл ставит своему отряду запреты и отдает приказы, даже порой не объясняя причины, может даже чересчур сильно давить на отбившихся от рук охотников, но старается не прибегать к насилию, руководствуясь главным правилом — все должно делаться во благо Дикой Охоты, все усилия вожака направляются на то, чтобы сделать свою стаю сильнее, а по-настоящему сильной она становится лишь при полном контроле. Кайл относится к своим подчиненным справедливо, никогда не самоутверждается за их счет и ценит вклад и заслуги каждого охотника — если, конечно, такие заслуги у него вообще есть. Вместе с тем он не лишен чувства собственной важности, которое демонстрирует, смотря на подчиненных немного свысока, однако к четырем Всадникам, имеющим в его глазах определенные "привилегии" в сравнении с другими, он относится не с высокомерием, а даже с любовью, любовью командира, становящегося для бойцов их вторым отцом.'}),(0,l.jsx)(n.p,{children:"Кайл не склонен юлить, хитрить, говорить загадками. Ему хватает и двойной жизни, которую он постоянно ведет, чтобы скрыть свой истинный кошмарный облик, а потому Блейк говорит только правду, даже не говорит, а рубит прямо в глаза, выбирая самый прямой путь, который обычно самый грубый и резкий. Он не будет плести паутину лжи, заманивая добычу в свою ловушку, словно паук, он будет, словно птица, парить над остальными так высоко, как позволят крылья. Ничтожных, слабых, жалких грешников Кайл просто не удостаивает вниманием с высоты своего полета. Достойными он признает только тех, кто силен как телом, так и духом, не теряющих самообладание и рассудок, тех, кто сделал себя сам и сам поднялся до вершин, кто не дает себя сломать и переделать, кто ни перед чем не отступает и верен своим принципам, тех, кто не труслив и не лицемерен. Таковы добродетели, которые чтит Кайл, и только к личностям, обладающими ими, вожак Дикой Охоты проявит свою благосклонность."}),(0,l.jsx)(n.p,{children:'Что же насчёт моральных принципов Кайла? Важнейший для него — это держать руки "чистыми", не вмешиваться в борьбу света и тьмы и позволить им решать конфликты друг с другом самостоятельно. Противостоять злу, как считает Кайл, следует лишь в том случае, если оно выходит из берегов, начиная распространяться бесконтрольно, во всех направлениях, сметая все на своем пути. Лишь тогда Дикая Охота под началом Кайла выступит, чтобы остановить нарастающую тьму, загнать ее обратно, не уничтожить, но сдержать, чтобы не дать тьме поглотить весь мир. Кайл знает о том, что к праведникам и злодеям этот мир относится совершенно по-разному, знает и не стремится становиться ни тем, ни другим. Сохранять баланс, допуская существование зла на земле как необходимости, но и не позволяя ему прорасти в землю слишком глубоко — вот идеология Кайла, а значит, такая же идеология будет и у всей Дикой Охоты. Не будет по-другому, пока Кайл находится у руля.'})]})}),(0,l.jsx)(r,{title:"Страхи",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Упадок Дикой Охоты",children:(0,l.jsx)(n.p,{children:"Страх, что поколение действительно способных воинов рано или поздно уйдет, а вместо них придут ни на что не годные беспомощные слабаки."})}),(0,l.jsx)(h,{title:"Неоправданные жертвы",children:(0,l.jsx)(n.p,{children:"Страх, что кровь была пролита Палачом напрасно, а цель оказалась ложной, что превратит его в обычного убийцу."})}),(0,l.jsx)(h,{title:"Деградация",children:(0,l.jsx)(n.p,{children:'Страх, что Кайл начнет ослабевать и терять хватку, боязнь стать "промахнувшимся Акеллой".'})}),(0,l.jsx)(h,{title:"Разоблачение",children:(0,l.jsx)(n.p,{children:"Страх, что лидера Дикой Охоты узнают в лицо."})}),(0,l.jsx)(h,{title:"Ухудшение отношений со Зверем Греха",children:(0,l.jsx)(n.p,{children:"Страх потери доступа к благословениям Проклятого Коня."})}),(0,l.jsx)(h,{title:"Отсутствие будущего",children:(0,l.jsx)(n.p,{children:"Страх за всё время бытия лидером Дикой Охоты так и не узнать, какая им уготована судьба."})})]})}),(0,l.jsx)(r,{title:"Мечты, цели",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"Уничтожить Черный Рынок — мечта Кайла, а его цель, которая поможет осуществить эту мечту — охотиться на грешников из нелегальных организаций от рядовых до самой верхушки, чтобы отправить их в темницу."}),(0,l.jsx)(n.p,{children:"Конфисковывать артефакты — продолжать собирать магические артефакты, конфискованные у нарушителей."}),(0,l.jsx)(n.p,{children:"Найти отца и брата — отец и брат Кайла, участвовавшие в войне, должны были попасть в Энкраж, и Кайл до сих пор не теряет надежды, что отыщет их."}),(0,l.jsx)(n.p,{children:"Узнать личность Ворона — Кайл пообещал себе отомстить писателю из Мемфиса за то, что тот пошёл против всей Дикой Охоты."}),(0,l.jsx)(n.p,{children:"Искупление в смерти — цель искупить грехи без последующего перерождения, что является основным условием контракта с Хранителем."}),(0,l.jsx)(n.p,{children:"Поиск ответов — узнать, для чего на самом деле существует Дикая Охота."})]})}),(0,l.jsx)(r,{title:"Биография (при жизни)",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"Эта история началась с рождения малыша по имени Франсиско Игнасио де Ариас в сентябре 1798 года в городе Картахена, в испанской колонии, именуемой вице-королевством Новая Гранада. Семья Франсиско была знатной, но все лавры отдавались его старшему брату, который вскоре должен был продолжить военную службу вслед за отцом, занимавшим почетное звание полковника в армии. Этим отец Франсиско, Луис Карлос де Ариас, был во многом обязан деду Франсиско, который владел одним из изумрудных рудников, имел большое влияние в обществе и помогал отцу с продвижением по службе. А теперь дед Франсиско, Мариано Рамирес де Ариас, покровительствовал своему внуку, чтобы тот не чувствовал себя обделенным вниманием."}),(0,l.jsx)(n.p,{children:"Когда мать Франсиско умерла, мальчику было всего 3 года, и он очень переживал из-за ее потери. Дед был первым, кто поддержал его, был рядом с ним, воспитывал вместе с супругой — бабушкой Франсиско. Когда внуку стало уже 9, дед спросил его, кем бы он хотел стать в будущем, и мальчик ответил, что хочет быть инженером, добывающим изумруды, которыми славится Колумбия. Дед пообещал, что обеспечит ему работу в руднике, и через несколько дней подарил внуку изумруд на память о своем обещании."}),(0,l.jsx)(n.p,{children:"В 12 лет Франсиско постепенно начал осознавать положение его семьи. В городе вся власть была у испанцев, прибывших в Картахену из Мадрида, а они, креольская знать, потомки все тех же испанцев и местного населения, не обладали никакими политическими правами, хотя благосостояние всего города держалось на них. Он еще не разбирался в налогах, которые специально выставлялись властями чрезмерно большими для креолов, но уже понимал, что при таком доходе, как у его семьи, они должны быть намного богаче. Франсиско мечтал, что когда-нибудь креолы будут править вместо испанцев, и их положение улучшится. И об этом мечтал не только он."}),(0,l.jsx)(n.p,{children:"В 1810 году в колонии разразилось восстание, в результате которого повстанцы свергли колониальную власть и образовали собственное правительство. Вице-королевство Новая Гранада распалось на 22 провинции. Многие из них открыто перестали признавать власть Мадрида, включая и Картахену, которая была первым городом, провозгласившим в 1811 году свою независимость. Провинции образовали конфедерацию, но оставался вопрос, в какой форме будет существовать их государство — унитарной или федеративной. На почве этого вопроса начались разногласия, которые в 1812 году привели к гражданской войне."}),(0,l.jsx)(n.p,{children:"В эту войну отец и брат Франсиско сражались на стороне федералистов, поддержав политического деятеля Торреса, который также принадлежал к креольской знати и стремился, свергнув господство Испании, установить новую власть. Между федералистами и унитариями произошло несколько сражений, в одном из которых 9 января 1813 года погиб Луис Карлос де Ариас. Уже в мае того же года гражданская война окончилась, и обе стороны смогли наконец объединиться против общего врага — испанцев. Но домой брат Франсиско, Хосе Антонио де Ариас, вернулся один."}),(0,l.jsx)(n.p,{children:'"Где наш отец? Когда я его увижу?" — спрашивал Франсиско. Брат лишь ответил с горечью: "Отец больше не вернется. Он погиб на войне". Затем Франсиско узнал, что война в конце концов закончилась примирением сторон, но это его нисколько не утешило. Мальчик плакал, повторяя сквозь слезы: "Ради чего погиб наш отец?", а сердце его сжималось от тоски. С той поры он понял, что война бессмысленна, ведется ради нелепых споров и претензий, а жертвами в этой бессмысленной борьбе становятся тысячи людей.'}),(0,l.jsx)(n.p,{children:"Испанцы воспользовались гражданской войной между повстанцами, чтобы сокрушить их. Однако в борьбе за независимость бывшей колонии приняла участие прибывшая из Венесуэлы освободительная армия Симона Боливара. В сентябре 1814 года армия Боливара прибыла в Картахену, и власти города встали на его сторону, а вместе с ними и Франсиско, которому исполнилось уже 16 лет. Для него Боливар был тем, кто сможет окончить эту ужасную войну, на него юноша возлагал большие надежды. Но многие не разделяли его мнения."}),(0,l.jsx)(n.p,{children:"Когда Боливар собирался отправляться на север, чтобы разгромить испанцев, власти Картахены пообещали направить ему войска, а также вооружение и боеприпасы. Но свое обещание они не сдержали, посчитав Боливара всего лишь идеалистом, амбиции которого были слишком велики для его молодого возраста. Боливар остался без поддержки. Между тем испанский король отправил огромную армию под предводительством маршала Морильо для подавления восстания в колонии. В марте 1815 года Боливар проиграл в битве против Морильо, а 8 мая вынужден был спасаться бегством на Ямайку, а потом и на Гаити, чтобы там собрать новую армию. Теперь ничто не мешало испанской армии продолжать свое наступление. Через несколько месяцев испанцы подошли к Картахене, и 23 июля началась осада города."}),(0,l.jsx)(n.p,{children:"Картахена была окружена испанцами и с моря, и с суши, но повстанцы вовсе не собирались легко сдаваться. Настроение у них было решительное, власти организовали ополчение из всех, кто мог держать оружие. В ополчение попал и юный Франсиско. Долгие пять месяцев Картахена держала оборону. За это время припасы подошли к концу, защитникам города приходилась питаться кожей и крысами, но даже тогда они не сдавались. Франсиско и его брат Хосе были истощены от голода, люди вокруг них умирали, но братья не опускали руки. Из всей семьи остались только они и дед Мариано, и теперь они должны были выстоять, чтобы никого больше не потерять."}),(0,l.jsx)(n.p,{children:"От безысходности всех раненых, детей и женщин решили выпустить из города в надежде, что испанцы их пощадят. До лагеря испанцев добралась только треть от всех, кто вышел из Картахены. Маршал Морильо принял их, но выдвинул ультиматум: если в течение трех дней ему не сдадут крепость, он отправит всех обратно в город. Даже после таких условий повстанцы отказались сдаваться. В ночь следующего дня они сели на корабли и попытались уплыть в сторону Ямайки, испортив все пушки перед отплытием. По ним открыли огонь испанцы, и к тому же корабли попали в бурю. Выбраться удалось далеко не всем, и корабль, на котором находился Франсиско, оказался из тех, кому не повезло. Испанские суда догоняли их, и юноша бросился в воду, прежде чем корабль повстанцев был захвачен."}),(0,l.jsx)(n.p,{children:"История Франсиско Игнасио де Ариаса на этом заканчивается. Найти его так и не удалось. Хосе Антонио де Ариас, его брат, попал в плен вместе с остальными повстанцами, и их заточили в темницу испанцы по возвращении в Картахену, которая теперь напоминала кладбище. Треть населения Картахены умерла от голода и болезней, прежде чем в город вошли захватчики. Испанский маршал Морильо пообещал помиловать защитников города, если те сложат оружие и сдадутся, и повесил их, как только повстанцы подчинились. Не пощадили даже стариков, женщин и детей — всех, кто сдался испанцам, безжалостно перерезали. Среди погибших был и Мариано Рамирес де Ариас, дед Хосе, который теперь томился в заключении. Установив власть в Картахене, Морильо создал трибунал инквизиции, к этому времени прекратившей свое существование, но возрожденной усилиями жестокого маршала. Надзирателям отдали приказ пытать заключенных, а также проводить допросы выжившего населения оккупированного города. Начался ужасающий испанский террор."}),(0,l.jsx)(n.p,{children:"Захватчики не думали, что у кого-то хватит сил оказать им действительно достойное сопротивление. И эта неосмотрительность привела к тому, что четверо испанских солдат, занявших дом, который ранее принадлежал роду де Ариас, были в одночасье убиты прямо в этом же доме, а когда это обнаружили, преступник успел скрыться, прихватив с собой найденную в доме провизию. Район тут же был оцеплен, но убийцу найти не удалось. Испанское командование не знало, орудовал ли один человек или группа, поэтому было принято решение ждать, когда им станет известно больше."}),(0,l.jsx)(n.p,{children:"Через три месяца один из патрулей, усиленных после массового убийства, был атакован. Откуда ни возьмись, словно тень, появился неизвестный, облаченный в черное, который молниеносно напал на испанских солдат, убил троих из пяти несколькими ударами ножей, которые он держал в обеих руках, а затем сбежал, прежде чем остальные ввязались с ним в бой. Двое оставшихся в живых солдат позднее рассказывали, что лицо убийцы было разрисовано углем и напоминало лицо призрака, восставшего из мертвых, а на вид он был совсем молод, в возрасте от 18 до 23 лет."}),(0,l.jsx)(n.p,{children:'Испанцы забили тревогу. Надо сказать, что во многих провинциях восставшей колонии начали действовать партизанские отряды, которые состояли в основном из простого народа. Они хорошо скрывались, неожиданно наносили удары и исчезали, прежде чем их удавалось поймать. Но этот случай был особенным: убийца, напоминавший призрака, охотился на своих жертв в пределах города и до сих пор не был схвачен. После нападения на патруль ему дали прозвище "Палач Картахены", а его упоминание наводило ужас на менее смелых солдат. Эти страхи только укрепились после следующей атаки Палача, которая произошла в 1817 году, примерно через год после предыдущего нападения.'}),(0,l.jsx)(n.p,{children:"Отряд из шести испанских солдат во главе с лейтенантом вошел в дом, где проживала семья уроженцев Картахены, чтобы допросить их по обвинению в восстании против Испании. Дело шло к тому, что отца семейства жестоко убили бы, как и случалось до этого, но убийству помешало вторжение Палача. Перед двумя солдатами, караулившими вход в дом, появилось выкрашенное углем лицо, в глазах которого горела ненависть, и после нескольких быстрых ударов те упали замертво. Затем убийца ворвался внутрь, вступая в схватку сразу с четырьмя. Положив двоих, Палач, ловко орудуя ножами, стал теснить третьего, но стоило ему довершить свое дело, как его окликнул капитан, взявший в заложники мужчину, которого ранее допрашивал. Испанец угрожал, что убьет повстанца, если противник не сдастся. Палач не стал ничего отвечать и швырнул в испанца ножом, прежде чем тот привел угрозу в исполнение. Нож угодил прямо в глаз капитану. Снаружи уже спешило подкрепление, и убийца, чья черная одежда уже была заляпана кровавыми брызгами, прыгнул прямо в окно, выломав его своим телом."}),(0,l.jsx)(n.p,{children:"Раненый осколками стекла от выбитого им же окна, Палач пытался скрыться от преследования, оставляя за собой кровавые следы. Испанцы жаждали мести за убитых товарищей и непременно настигли бы убийцу, если бы тому на пути не встретился неожиданный союзник. Цыганка, жившая в трущобах Картахены, пришла на помощь Палачу, спрятала в своем убежище и укрывала, пока его раны не зажили. Она жила совершенно одна, мужа ее забрали испанцы и публично казнили. Ей Палач смог довериться и сообщил, что ищет своего брата. Цыганка по имени Росарио Хименес рассказала, что Хосе Антонио все еще жив, но испанцы собираются казнить и его. Она также подарила Палачу большую цыганскую иглу для шитья и взяла с него обещание, что тот уколет этой иглой, на которую она навела порчу, капитана испанцев, казнившего ее мужа. Взамен она рассказала, в какой темнице держат Хосе Антонио."}),(0,l.jsx)(n.p,{children:"Палач вел наблюдение за тюрьмой, куда попасть было весьма трудно, а выбраться из нее было и вовсе невозможно. Прошло практически восемь месяцев, в течение которых он старался не показываться испанцам на глаза, тащил любую еду, до которой удавалось дотянуться, а в периоды, когда с пропитанием ему не везло, мог голодать неделями. День казни он все же не пропустил. Хосе Антонио появился в сопровождении конвоя, который вел его во внутренний двор тюрьмы на казнь. Палач подготовился заранее, все эти месяцы копая по ночам под стеной темницы подземный ход, ведущий к внутреннему дворику, и сегодня наконец им воспользовался, дождавшись момента, когда можно будет проскочить незаметно. Когда до казни оставались считанные минуты, во дворе сверкнула молния черного цвета, метнувшись к испанцам. Одного из солдат Палач сбил с ног, другого убил ударом ножа, у третьего выбил оружие и им отразил атаку четвертого. В суматохе он схватил Хосе Антонио и потащил его к подземному ходу, из которого пришел. Затем Палач отбивался от солдат, пока его брат полз под землей. Среди солдат был капитан, которому в бою удалось ранить диверсанта в черном своим клинком. К тому же вскоре должно было подойти подкрепление, и тогда у него не было бы ни единого шанса. Но тут Палач вспомнил о своем обещании, провел финт ножом и тут же вонзил капитану в прорезь его шлема подаренную цыганкой иглу. Капитан от такого удара упал на землю, остальные солдаты обратили на это внимание, замешкались, и это спасло Палачу жизнь. Точно крот, он зарылся под землю и быстро выбрался с другой стороны."}),(0,l.jsx)(n.p,{children:"После этого события в городе начались волнения, и солдатам приходилось подавлять беспорядки. Им было уже не до Палача Картахены, который в это время снова скрылся из виду. Когда ситуация в городе улеглась, ему удалось найти Хосе Антонио, который был в безопасности у одного из друзей. И Хосе, и его друг заметили Палача, но не стали бить тревогу.\n— Береги себя, — сказал человек в черном и собрался уже уходить, как тут Хосе с надеждой в голосе спросил:\n— Мы случайно не знакомы? Я где-то, кажется, слышал твой голос.\nПалач обернулся к нему.\n— Нет, мы не знакомы. Прощай, — не колеблясь, ответил он и быстрым шагом ушел в никуда."}),(0,l.jsx)(n.p,{children:"Хосе Антонио, последний из рода де Ариас, позже присоединился к партизанам, а через год, в 1819 году, помогал Симону Боливару в его очередной попытке освободить Южную Америку. Эта попытка оказалась успешной. Спустя два года, в 1821 году, была освобождена и Картахена. Но к этому времени Палача там уже не было. Совершив еще пару нападений на испанцев, он в 1819 году, когда Симон Боливар стал президентом федеративной республики Колумбия, провозглашенной после ее освобождения, исчез и больше не появлялся в этих местах."}),(0,l.jsx)(n.p,{children:"Тот, кто скрывался под личиной Палача, затем нанялся матросом на корабль, оказался на британской Ямайке, где жил несколько лет. На Ямайке он впервые стал называть себя Кайл Блейк — распространенное, непримечательное имя для британца. Под этим именем мужчина и жил, пока у властей Ямайки не стали возникать вопросы по поводу его настоящего происхождения. Заметив подозрения с их стороны, Кайл, не дожидаясь разбирательства, уплыл из Ямайки, направляясь в сторону острова Гаити. Он поселился в Санто-Доминго, бывшей испанской колонии, в 1821 году провозгласившей свою независимость, а в 1822 году присоединенной к республике Гаити, также совсем недавно, в 1804 году, ставшей независимым государством. Здесь царила свобода, и вопросов к правдоподобности происхождения Кайла Блейка не возникало совсем, так что мужчине удалось тут обжиться."}),(0,l.jsx)(n.p,{children:"Кайл собирался начать на этом месте новую жизнь, наконец завести свою семью, которую не уничтожит война. Спустя два года у него это получилось — у Кайла завязались отношения с афроамериканкой, прибывшей вместе с другими эмигрантами из США в 1824 году, а в следующем году они уже жили вместе. В Санто-Доминго было много испаноговорящих людей, но Кайл хотел по возможности забыть свое прошлое, в котором он говорил по-испански и носил испанское имя. Теперь он считал, что сможет наконец стать счастливым, но время показало, что он ошибался."}),(0,l.jsx)(n.p,{children:"В 1825 году президенту Гаити пришлось выплатить Франции огромную компенсацию в размере 150 миллионов франков, в противном случае та отказывалась признавать полную независимость Гаити. Чтобы выплатить эту сумму, пришлось брать заем и влезать в долги. Экономика Гаити оказалась подорвана. Все эти условия были самыми благоприятными для расцвета преступности, которая достаточно быстро организовала свой подпольный рынок. Следующие четыре года Кайлу пришлось выживать в ужасных условиях, к которым привело разрастание черного рынка и усиление его влияния. Повсюду стали множиться преступные группировки, законы не могли воздействовать на экономику, поскольку их поразила коррупция, а обложить налогами черный рынок не удавалось. Товаров становилось все меньше, так как не все выдерживали конкуренцию с черным рынком, а то, что продавалось на самом черном рынке, по качеству оставляло желать лучшего или вообще было подделкой. Найти приличную работу с хорошим заработком было чрезвычайно трудно, тем более в столь бедной стране, как Гаити, а присоединяться к бандитам Кайл не желал. Вместо этого он решил вести с ними войну, когда его терпение окончательно лопнуло. Во всех своих бедах, в катастрофической бедности, в которой Кайл жил, он винил теперь черный рынок и собирался с ним покончить."}),(0,l.jsx)(n.p,{children:"Одной ночью 1829 года Кайл вновь вооружился двумя ножами и неслышно ушел из дома. Под утро он уже спокойно спал в своей кровати, а один мелкий торгаш был найден с перерезанным горлом на территории, принадлежавшей черному рынку. Деньги у него исчезли, а чуть позже кто-то заплатил одной из уличных банд, чтобы те разгромили еще одну лавочку нелегального торговца. Неизвестный спустя месяц также напал на группировку, охранявшую склад другого торговца, разбогатевшего благодаря черному рынку, убил семерых, включая главаря, присвоил склад себе, а самого торговца выкинул из окна. Затем из этого склада он стал устраивать сделки с бандами, натравливая их на торговцев и друг на друга. Супруга вскоре узнала о делах Кайла, но не только не отвернулась от него, а договорилась со знакомым из банды афроамериканцев, чтобы та прикрывала Кайла в обмен на небольшое вознаграждение каждый месяц."}),(0,l.jsx)(n.p,{children:"Полтора года Кайлу удавалось наводить шороху на черный рынок, громя мошенников и дельцов, пока он не взялся за одного чиновника-взяточника, привязав его мертвое тело к столбу. После этого случая он привлек к себе внимание сверху. Кто-то вышел на банду афроамериканцев, заставил их расколоться, и вскоре Кайл неожиданно для себя проснулся ночью в горящем доме. Ему едва удалось спасти из пожара жену и спастись самому. Поджог, очевидно, был намеренный, но следов поджигателя найти не удалось. После того, как Кайл чудом избежал смерти, он решил оставить черный рынок в покое. Со временем он даже открыл ювелирную мастерскую, вспомнив, что в раннем детстве мечтал заняться этим ремеслом."}),(0,l.jsx)(n.p,{children:"В 1834 году его жена вдруг тяжело заболела. В поисках хорошего врача здесь, в Гаити, Кайл потратил много времени, затем был вынужден заказывать для нее лекарства издалека, заплатив огромные деньги, но все это не помогало. Изучив лекарства, медик заключил, что Кайлу продали просроченные препараты. Блейк пытался найти другие, которые помогли бы супруге, но было уже поздно — спасти ее не удалось. То, что приносило в его жизнь мир и спокойствие, исчезло. В знак скорби по любимой женщине Кайл облачился в черное, но вдобавок окрасил свое лицо углем, как уже делал когда-то в Картахене, изобразив настоящий лик смерти."}),(0,l.jsx)(n.p,{children:"Палач снова вернулся."}),(0,l.jsx)(n.p,{children:"Он напал на аптечную лавку, в которой заказывал лекарства для больной жены, ночью, когда продавцы заключали очередную тайную сделку. Клиента Палач убил на месте, аптекарей же связал, одному затолкал в глотку его же таблетки, так что тот задохнулся, второму прибил руки к прилавку, а ноги к полу, после чего раскроил череп молотком. В этот раз оружием было все, что попалось под руку, не только ножи."}),(0,l.jsx)(n.p,{children:"Санто-Доминго охватил страх. Убийца был объявлен в розыск, но не только власти хотели поймать Палача. Черный рынок объявил награду за его голову, и один из охотников зашел дальше всех, найдя список клиентов аптеки и вычислив среди них Кайла, у которого в прошлом уже были проблемы с черным рынком. На это у него ушло несколько недель, после чего он продал эту информацию другим охотникам. Кайла атаковали прямо в его мастерской, мужчина был не готов к такому, но все же вовремя опомнился и в бою нанес смертельные раны всем нападавшим, отделавшись лишь небольшими ранениями. Только вот, как оказалось, одному из охотников Палач, ошеломленный от внезапной атаки, нанес вовсе не смертельные раны, а тяжелые, и не заметил этого лишь из-за безразличия, которое чувствовал ко всему происходящему. Охотника вовремя нашли и прооперировали, а когда тот восстановил силы, очень долго потом искал новое убежище Палача, чтобы отомстить, и поиски его закончились только в 1836 году. Выследив свою цель, охотник на расстоянии подстрелил его из арбалета, но долго еще не решался подойти ближе, пока Кайл проклинал его на все лады."}),(0,l.jsx)(n.p,{children:'Наконец охотник приблизился, когда Кайл затих, но тут же выстрелил повторно в упор, не давая хитроумному Палачу возможности ответить.\n"Ты… Почему ты… выжил…", — были последние слова Кайла Блейка. Он так и не смог смириться с несправедливостью жизни, при которой избежал смерти именно охотник за головами, а не его супруга. Черный рынок оказался сильнее, и эту зависть к живучей, паразитирующей на других людях химере Кайл сохранит в себе и после смерти.'})]})}),(0,l.jsx)(r,{title:"Жизнь в Энкраже",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"Попав в Башню, Кайл выдержал все испытания не без помощи трех духов, сопровождавших его на пути и выручавших в моменты, когда грешник не мог справиться сам. Лишь в конце своего пути, когда он увидел тех же духов возле выхода из Башни, у них появилась более конкретная форма. Отец, мать и брат, имен которых Кайл даже не помнил. Как они с ним связаны, грешник тоже не мог вспомнить, но при последней встрече с духами отца и брата Кайл вдруг выразил желание продолжать с ними путь и после Башни. Мать же умерла слишком рано, и чувства к ней у Кайла не успели сформироваться, поэтому он даже не стал с ней говорить. Два других духа поделились своими силами с Кайлом в последний раз, и впоследствии при первом вызове своих гончих Кайл назовет их в честь своих родных, храня таким образом память о них. Луис и Хосе. Третьей гончей, как у других призраков Дикой Охоты, у него не было."}),(0,l.jsx)(n.p,{children:"Первое время Кайл бродил по общежитию, общаясь с другими грешниками, и еще не понимал, что несет в себе их необычная, порой даже странная внешность. Поэтому он с легкостью доверился нескольким темнокожим грешникам с острыми ушами, которые проявили к нему дружелюбие и предложили ему вместе исследовать коридоры замка и назначили время встречи на следующий день. Когда Кайл почти добрался до условленного места, где его должны были ждать, его перехватил незнакомый ему грешник, отвел в сторону и сообщил, что он ищет группировку низших дроу, которые заманивают неопытных грешников в коридоры и похищают их. Когда после всех объяснений и разговоров они уже вдвоем пришли на место встречи, там уже никого не было — преступники были достаточно хитры, чтобы понять, что их раскусили. Это было лишь подтверждением того, что незнакомец говорил правду."}),(0,l.jsx)(n.p,{children:'Тогда-то он и представился Кайлу, а затем предложил ему прогуляться вместе за пределы замка, чтобы познакомить его со своими "кровными братьями по оружию". Пока Кайл пытался понять, что все это значит, его новый знакомый что-то сказал ему, после чего сознание его отключилось, а очнулся он лишь спустя время, вдалеке от замка, в окружении незнакомых ему людей. Это была первая встреча Кайла с Дикой Охотой, а тот, кто привел его сюда, был ее лидером.'}),(0,l.jsx)(n.p,{children:"Кайл узнал прошлое Дикой Охоты, узнал, что она существует поколениями, что нынешнее поколение — первое после тех событий, которые произошли более чем сто лет назад, когда все призраки Дикой Охоты погибли. Он также узнал, что одновременно Дикая Охота может быть представлена не более чем десятью грешниками, и самое главное — что появления Кайла ждали после того, как умер один из них. С него началось новое поколение призраков Дикой Охоты, и нынешний лидер принял решение сделать его своим преемником. Кайл даже не смог ему возразить или как-то пойти против его воли. Сказанное предводителем Дикой Охоты должно быть непременно исполнено — таков был принцип воина, который принял Кайла новобранцем, а затем обучил всему, что знал сам."}),(0,l.jsx)(n.p,{children:"В течение того же года Кайл тренировался вместе со своим командиром, а затем однажды, когда они охотились где-то на севере, предводитель Дикой Охоты, который нес дозор и охранял сон Кайла, вдруг исчез, а Кайл даже ничего не почувствовал, когда проснулся. Для него лидер никуда и не уходил, кровь его продолжала течь по той же самой реке, в которой текла кровь Кайла. Иногда новоизбранный лидер даже слышал голос своего предшественника. Оставался лишь один вопрос — откуда появилась эта река? Кто ее основал?"}),(0,l.jsx)(n.p,{children:"Хранитель на этот вопрос не дал ответа, даже после того, как Кайл возглавил всю Дикую Охоту. Его кровным было все равно, сменился лидер или нет, они чувствовали в нем силу, которая была у каждого предводителя Дикой Охоты, и подчинялись ему. Тем не менее, сила эта досталась новичку, и относились соратники к Кайлу соответствующе. Пока новый лидер не набрался опыта, в боевых поручениях Хранителя рядом с ним был Мэттью Бейтс — один из четырех призраков Дикой Охоты, отличавшихся особой меткой и известных как Всадники Апокалипсиса. Среди них Мэтт был старейшим и носил прозвище Всадник Смерти. Но даже он не знал, для чего существует Дикая Охота, о чем прямо и сказал Кайлу, когда тот задал ему этот вопрос."}),(0,l.jsx)(n.p,{children:"Спустя двадцать лет после своего перерождения Дикая Охота под предводительством Кайла выследила и поймала всю группировку низших дроу, охотившихся на грешников в коридорах замка. Когда-то они едва не поймали в свою ловушку самого Кайла. Разумеется, тот прекрасно об этом помнил. Злопамятный охотник скомандовал своей команде соорудить виселицу из столбов и поперечной балки перед общежитием, на которой и повесил сразу всех. Вскоре у общежития собралась толпа, которая наблюдала, как отряд закованных в доспехи воинов методично вешает тёмных эльфов на виселице, подножие которой было окутано туманом.\n— Мы — Дикая Охота! Мы вернулись, чтобы вершить правосудие! — объявил командир отряда, когда казнь была завершена. — Эти отбросы творили бесчисленные злодеяния, и за это они болтаются в петле! Каждый, кто станет причинять другим грешникам зло, будет иметь дело с нами и понесет наказание от наших рук!"}),(0,l.jsx)(n.p,{children:"Преступники висели так несколько недель — Дикая Охота запретила снимать их с петли. Вскоре охотники сами явились за дроу и бросили их в темницу, откуда нарушители закона попадали во владения Сталкера. После этого случая о Дикой Охоте стали говорить шепотом, а его лидера называли не иначе, как Палач."}),(0,l.jsx)(n.p,{children:'С того момента Дикая Охота действительно стала следить за порядком. В 1860 году становится известно о мятеже низших сословий бааван ши, который затем в истории получил название "Война Пажей и Крестьян". В марте того же года герцогиня Лилит обратилась к Дикой Охоте за помощью в подавлении беспорядков, из-за которых Лилит и ее союзники не могли заниматься охраной бастиона, а кроме того, один из ее союзников, герцог де Сермо, погиб в бою с мятежниками. Когда Дикая Охота пришла на помощь, герцогиню Лилит уже взяли в плен. Благодаря посредничеству охотников был организован обмен главы мятежников, находящегося в плену Алого Двора, на Лилит. Когда обмен был совершен, Лилит смогла вернуть себе замок. Однако война была не окончена, и мятежники начали наступать на замок герцогини. В мае произошла последняя битва в этой войне, в которой герцогине Лилит удалось победить в бою главу мятежников, несмотря на численное преимущество нападавших. Мятежные бааван ши затем были схвачены Дикой Охотой и брошены в темницу.'}),(0,l.jsx)(n.p,{children:"В то же время Дикая Охота начала сотрудничать с Эрнестом Клайном, и совместно они стали ловить преступников еще чаще. Дикая Охота прибывала на место преступления, получала всю необходимую информацию от Эрнеста и по уликам находила виновных, которые затем попадали в темницу. Преступников хватало в большом количестве, учитывая начавшуюся в людском мире гражданскую войну в США. Дела у Кайла и его отряда шли неплохо, но лидер оставался недоволен. Он считал, что Дикая Охота создана для чего-то большего. Кайл был уже матерым охотником, он научился побеждать самых разных врагов среди обитателей Энкража, выходил победителем из многих сражений. Ему нужен был действительно достойный соперник, и Черный рынок, давно мозоливший ему глаза, мог бы стать именно таким. У нового лидера были большие амбиции, и он вынашивал их очень долго, до 1870 года. О своих планах он рассказал лишь своим подчиненным, не выступая перед всеми грешниками.\n— Мы говорим, что охотимся за преступниками, но разве это охота? Как можно преследовать зло и при этом позволять процветать источнику всего зла?! — негодующе спрашивал Кайл. — Чтобы начать настоящую охоту, мы должны отправиться в логово зверя! Черный рынок слишком долго упивался свободой, и с этого дня мы выступим против него всеми своими силами! Я не буду вызывать на бой ублюдков, которые прячутся в тенях, я буду наносить им удар за ударом, пока рынок не перестанет вести свои грязные делишки!"}),(0,l.jsx)(n.p,{children:'Так началась подготовка к войне, которую Кайл назвал Крестовым походом против Черного рынка. За годы подготовки каждый из призраков Дикой Охоты хотя бы раз, но побывал в баре "Черный Змей", узнавая о структуре Черного рынка, о методах его работы, об его иерархии. Это было достаточно просто сделать, поскольку Черный рынок, ощущая свою полную безнаказанность, даже не старался скрываться. В то время доступ к бару для Дикой Охоты еще не был закрыт, а вражда между ними еще не достигла своего пика, но вскоре все изменилось. Дикая Охота смогла прославиться, но вовсе не так, как хотел Кайл.'}),(0,l.jsx)(n.p,{children:"К 1876 году Кайл, едва разменявший сорок лет в новом мире, перешел от подготовки к действиям. Поводом для агрессии против Черного рынка стала помощь Вальгардам, которые просили у Дикой Охоты помощи в защите животных от браконьеров из Забытого Карнавала. Отбив несколько нападений охотников, отряд Дикой Охоты упустил нескольких из них. Кайл быстро усвоил свои ошибки и в следующий раз ему удалось вовремя засечь действовавшего в одиночку хантера Карнавала. Дикая Охота набросилась на него и связала, не давая ему возможности для побега. Тело охотника позже обнаружили подвешенным вверх ногами у разрушенного фонтана. Состояние его было ужасающим — Кайл своим охотничьим ножом собственноручно содрал с него кожу. Затем браконьера бросили в темницу, как и других преступников."}),(0,l.jsx)(n.p,{children:"В том же году Дикая Охота начала особенно пристально следить за операциями, которые проделывал Мемфис. Для грешников, обратившихся в Черный рынок, участники Мемфиса доставляли из людского мира все, что они только пожелают. Одного из таких доставщиков Кайл и его бойцы поймали с поличным в 1877 году, когда тот нес контрабанду. Преступнику отрубили руки, переломали ноги и привязали к столу в общежитии. Там он находился до тех пор, пока охотники не доставили его в темницу."}),(0,l.jsx)(n.p,{children:"Самой сложной целью был Орден, который был наиболее тесно связан с обществом грешников, проник в него настолько глубоко, что вывести их на чистую воду было чрезвычайно трудно. К тому же глава Ордена был весьма влиятельным, обладал необычными способностями, и даже попадание в плен к Сталкеру не смогло сокрушить его волю. Ему-то Кайл и решил бросить вызов. Воодушевленный прошлыми победами, лидер Дикой Охоты замахнулся на одного из элитных рыцарей Ордена по прозвищу Фантом. У охотников давно был зуб на неё, поскольку Фантом совершала нападения на грешников в коридорах и в туманном лесу. Для Дикой Охоты была важна любая информация о ее передвижениях, и когда в 1878 году прошла весть, что Фантома заметили в туманном лесу, Кайл, узнав об этом, тут же созвал весь свой отряд и бросился в лес."}),(0,l.jsx)(n.p,{children:"Операция по захвату Фантома обернулась катастрофой. В лесу ее не оказалось, а слухи о том, что ее там видели, распустили члены самого Ордена, чтобы заманить Дикую Охоту в ловушку. Вместо одного орденского рыцаря их встретил Моран вместе со своей свитой. В тяжелом бою Кайл и его отряд проиграли, несмотря на отчаянное сопротивление, и всех охотников связали, надежно обездвижив. Кайл ждал, что предпримет Моран, и был готов отвечать за этот провал своей головой. Моран ему такой возможности не предоставил. Глава Ордена подозвал к себе своих рыцарей и указал на одного из охотников. Его притащили прямо к Морану.\n— Прекрати! — вмешался Кайл, попытавшись вырваться от орденских бандитов, державших его. Моран тут же обернулся к нему.\n— Хочешь продолжить этот танец? Тогда подсчитай свои ходы, ведь к концу останется лишь один из танцоров. А теперь, — глава Ордена взглянул на другого охотника, чтобы вынести приговор: — в болото его."}),(0,l.jsx)(n.p,{children:"Кайл не успел ничего ответить, как его соратника подхватили и уволокли в сторону туманных болот, пожирающих грешников живьем. Это был последний раз, когда Кайл его видел. Так лидер Дикой Охоты лишился своего бойца, и вместе с тем вышел из игры, которую сам и затеял."}),(0,l.jsx)(n.p,{children:'Впервые Дикая Охота потерпела столь сокрушительное поражение. Стычек с Мораном или с другими членами Ордена у Дикой Охоты больше не было, но они не забыли о том, какую жертву принесли в этой войне, просто не желали терять и других бойцов. В будущее они смотрели с тревогой, и не зря — их злоключения на этом не закончились. В 1879 году Дикую Охоту настигло возмездие Мемфиса. Некто из этой организации, известный своим писательским талантом и носивший прозвище Ворон, опубликовал статью под названием "Палачи среди нас". Статья начиналась с портрета, в котором ошеломленный Кайл узнал своего погибшего товарища, убитого Мораном. Далее рассказывалась вся подноготная об охотнике, перечислялось абсолютно все, за чем его удалось заметить. Статья завершалась призывом разоблачить оставшихся участников Дикой Охоты, за каждого из которых Ворон сулил неплохую награду. За разоблачение лидера Дикой Охоты был гарантирован прием в Мемфис без предварительных испытаний с возможностью занять там один из высоких постов.'}),(0,l.jsx)(n.p,{children:"Кайл рассвирепел. Каждый его патруль теперь начинался с того, что охотники искали экземпляры статьи, собирали их в большую кучу и сжигали. Ничего из этого не помогало, наоборот, статья приобрела еще большую популярность в 1880 году. Пришлось оставить попытки уничтожить писанину Ворона. Статья вышла в небольшом тираже, однако экземпляров осталось еще достаточно, они и теперь хранятся кое-где, но быть пойманным с этой статьей Дикой Охотой означало нарваться на большие неприятности. Тем не менее своей цели Ворон добился, и среди прочитавших статью нашлось много тех, кто пытался разоблачить хотя бы кого-нибудь из Дикой Охоты. Кайлу и его отряду приходилось соблюдать осторожность и до минимума сократить появление среди грешников как в истинном облике, так и в своём обычном. Так продолжалось около двадцати лет, прежде чем шумиха хоть немного утихла."}),(0,l.jsx)(n.p,{children:"Когда Дикая Охота наконец смогла действовать свободно, Кайл начал расследование по поиску Ворона — прощать столь дерзкий поступок лидер Дикой Охоты не собирался. Охотники остановились на двух подозреваемых — Кирино Понсе де Леон и Раймон Диас. Расследование началось со слежки за Кирино, так как тот был наиболее легкой целью. К 1909 году стало понятно, что Кирино не является Вороном."}),(0,l.jsx)(n.p,{children:"В 1910 году в окрестностях замка вдруг объявился темный сикигами, по принадлежности напоминавший катастрофного. В замке тут же объявили чрезвычайное положение и вызвали Дикую Охоту для борьбы с сикигами, устраивавшим нападения на всех встреченных ему грешников и оставлявшим позади себя лишь хаос и разрушения. Дикая Охота во главе с Кайлом выступила против враждебного духа всем строем, облачившись в доспехи. В тяжелом бою с сикигами охотники смогли его ослабить и заставить отступить. Затем началось преследование — нужно было найти призывателя, который был настоящим источником угрозы. Охотники теряли след, снова находили, сражались с сикигами повторно, шли по его следам, и их охота завершилась только тогда, когда дух смог вернуться к своему хозяину. Призывателем оказалась маленькая девочка, на теле которой охотники обнаружили несколько магических печатей неизвестного назначения. В процессе разговоров с девочкой Дикая Охота выяснила, что ее долгое время держали в клетке под землей и заставляли подчиняться разным приказам, порой самым ужасным, но потом девочке удалось выбраться из подземелий."}),(0,l.jsx)(n.p,{children:"Юную призывательницу Кайл передал Магистериуму — организации, созданной оммедзи. Сначала Магистериум не желал брать опеку над девочкой, ссылаясь на то, что с такими грешниками должен разбираться Сталкер. По какой-то причине Палач проявил сострадание к маленькой грешнице и убеждал руководство Магистериума попробовать ее перевоспитать, так как она совершала призыв сикигами не по своей воле, а наказание отложить. Благодаря поручительству Кайла оммедзи так и не встретилась со Сталкером. Оставалось теперь найти культистов, в плену у которых и находилась девочка. Дикая Охота четыре года боролась с культистами, спускаясь в подземелья, где те обитали, но затем в людском мире грянула Первая мировая война, и о культе пришлось на время забыть."}),(0,l.jsx)(n.p,{children:"Мировая война привела к большому количеству жертв, и те, кто успел забрать чью-то жизнь в бою, прежде чем лишиться своей, в Энкраже зачастую становились преступниками. Работы у Дикой Охоты заметно прибавилось — каждый год, пока шла мировая война, для Кайла считался за десять лет, настолько часто ему приходилось сталкиваться с волнами преступности. Даже после окончания войны Дикой Охоте было нелегко, лишь к 1922 году наступило затишье."}),(0,l.jsx)(n.p,{children:"Как только у Кайла появилась возможность, он снова продолжил борьбу с Черным рынком, поскольку до сих пор не соглашался зарыть топор войны. Однако предыдущие стычки научили его вести борьбу осторожнее, и Кайл действовал лишь в рамках помощи Вальгардам, отражая нападения охотников Забытого Карнавала на зверей, но не преследуя этих охотников. Лишь раз в 1923 году Кайл изменил своему правилу, погнавшись за серебряным охотником, который ему особенно не понравился своей жестокостью. Этим охотником был Август Линдберг, и во время погони он отстреливался от Дикой Охоты так яростно, что ему даже удалось ранить Кайла. Настигнуть Августа так и не удалось. Однако в 1924 году Дикой Охоте удалось взять в плен двух участников Карнавала. Кайл пытался пытками выведать у них хоть какую-то информацию о составе организации, но ничего не добился и просто отправил охотников в темницу."}),(0,l.jsx)(n.p,{children:"В 1925 году Дикая Охота решила начать сбор информации о Раймоне Диасе, чтобы выяснить, является ли тот Вороном. Охотники около двух лет следили за скрытным лисом, но так и не получили убедительного ответа на свой вопрос. Тем не менее, удалось выяснить, что Раймон совершает сделки с грешниками, желающими обратиться за его услугами. Так как Раймон был связан с Орденом, Дикая Охота не могла вмешиваться открыто, чтобы не произошло повторного конфликта. Кайл решил рискнуть и в 1927 году сам начал искать встречи с Раймоном. Несмотря на отсутствие явных доказательств, лидер Дикой Охоты был уверен, что именно он скрывается под псевдонимом Ворон."}),(0,l.jsx)(n.p,{children:'Клиентом Черного рынка Кайл на тот момент стать уже не мог — после конфликта с Орденом Моран принял все меры для того, чтобы закрыть Дикой Охоте доступ к бару "Черный змей". Поэтому приходилось хитрить, использовать уловки, и все это делать таким образом, чтобы не вызвать у Раймона подозрений. В 1928 году Кайлу удалось договориться о встрече с Раймоном. На встречу призрак Дикой Охоты явился один, без доспехов, прикрыв свое лицо тьмой, и без предупреждения атаковал Диаса. Проницательный Раймон вовремя почувствовал опасность и поместил своего противника в иллюзию при помощи Карты Ужаса. В то время, как Кайл метался в лабиринте зеркал, Раймон попытался проникнуть за покров тьмы и увидеть его лицо, но тьма, скрывавшая лицо грешника, оказалась настоящей, а не иллюзорной. Когда Кайл смог вырваться из лабиринта, вернувшись в реальность, Раймон исчез. Был ли он Вороном или нет, осталось загадкой.'}),(0,l.jsx)(n.p,{children:'Последующие десять лет после поражения Раймону Кайл развивал свои боевые навыки и способности. Именно в тот период мужчина впервые начал обучаться стрельбе из револьвера, а затем, освоив это оружие, стал использовать его вместе со своими излюбленными ножами. Испробовав различные модели револьверов, Кайл остановился на нагане и с этим револьвером впоследствии прошел многие и многие трудности. Особенно часто пускать свое новое оружие в ход ему пришлось, начиная с 1939 года, когда в людском мире началась Вторая мировая война. У Дикой Охоты уже был опыт борьбы с наплывом преступников в годы Первой мировой, но усмирять грешников, переродившихся после новой войны, оказалось на порядок сложнее, к тому же преступников было больше и количественно. Многие помогали Дикой Охоте в устранении хаоса, образовавшегося в те годы, и к 1946 году порядок общими усилиями был восстановлен. "Вы все могли бы носить медали как ветераны войны", — говорил своим бойцам Кайл, который был предводителем охотников в обеих войнах. К этому моменту состав Дикой Охоты успел частично измениться — несколько охотников из старого поколения покинули этот мир, и вместо них переродились новые грешники, для которых лидером всегда был и оставался только Кайл Блейк. По мере того, как постепенно сменялось поколение, авторитет Кайла в своем отряде возрастал. Но самым главным для лидера охотников было то, что новички не видели первого столкновения Дикой Охоты с Орденом, не помнили этого провала. А Кайл очень давно жаждал реванша.'}),(0,l.jsx)(n.p,{children:"К концу 1946 года налеты охотников на орденских наемников наконец принесли результат — отряду Кайла удалось захватить Солера фон Клейста. Экзекуции рыцарь Ордена не дождался, поскольку его товарищи по организации атаковали Дикую Охоту, чтобы спасти пленного. Поначалу Кайл не собирался уступать, не отступал и Орден, и когда одного из охотников в том бою едва не убили, Кайл, не желая смерти своих бойцов, практически отдал Ордену Солера."}),(0,l.jsx)(n.p,{children:"Затем в жизни Кайла наступил период, когда он вновь задумался о предназначении Дикой Охоты, есть ли хоть какой-то смысл в том, что они делают, не упускают ли они чего-то. С этими вопросами охотники стали посещать территорию Зверя Греха, совершив первое паломничество в 1947 году, и с тех пор стали время от времени туда заходить, укрепляя связь Дикой Охоты с Проклятым конем. Никто из Дикой Охоты не мог служить стражем у Зверя Греха или занимать другой титул — их основным приоритетом было служение Хранителю. Из-за этого налаживание отношений со своим покровителем проходило у охотников достаточно долго, вплоть до 1954 года."}),(0,l.jsx)(n.p,{children:'В 1955 году случилась диверсия в темнице, первая за всю историю существования современной Дикой Охоты. Некто открыл место заключения всех преступников, которых поймали охотники и за которыми еще не пришел Сталкер, и выпустил их на свободу. По слухам, за этим стоял загадочный глава Мемфиса, но подтверждений этому не было. Так или иначе, опасные преступники снова оказались на свободе, и в этот раз они действовали сообща, чтобы Дикая Охота не смогла переловить их поодиночке. К тому же обратно в темницу им не хотелось, поэтому сбежавшие грешники скрывались как могли. Лишь в 1958 году Кайл бросил в темницу последнего из них. Он хотел, чтобы беглецы еще очень долго сожалели о том, что осмелились покинуть темницу, и каждый из них, оказавшись в плену у Дикой Охоты, подвергался "смерти от тысячи порезов", когда от преступника постепенно отрезали по кусочку от тела. После этого события даже те грешники, что еще не видели становление Палача воочию, убедились в том, что такое прозвище он носит неспроста.'}),(0,l.jsx)(n.p,{children:"В то время, как Дикая Охота была занята диверсией, грешник по прозвищу Тринадцатый Бог, который уже находился в розыске за причинение увечий грешникам, выкрал особо ценный пергамент, из-за чего его стал преследовать Сталкер. Хранитель также поручил Дикой Охоте найти его и доставить в темницу для правосудия. Охотники выслеживали его много лет, но Тринадцатый Бог постоянно ускользал от них — его укрывал Черный рынок, с которым грешник сотрудничал. Погоня за ним велась вплоть до 1967 года, пока Кайл и его отряд не зашли в тупик окончательно."}),(0,l.jsx)(n.p,{children:"Преступнику удалось скрыться, и на этом охоту пришлось приостановить."}),(0,l.jsx)(n.p,{children:"В дальнейшем Дикая Охота занималась помощью Вальгардам, вовремя реагируя на нападения браконьеров и отгоняя их от животных. И вновь Кайл Блейк пришел к тому, что цель существования призраков Дикой Охоты в этом мире ему до сих пор не понятна. Карать преступников — благородное дело, но ведь не только ради этого Темные Отец и Мать сотворили проклятых всадников. Для чего же тогда? С этими вопросами Кайл вновь решил обратиться к Зверю Греха. В 1973 охотники совершили уже второе паломничество, практически до конца семидесятых годов совершая визиты на территорию Проклятого коня, нередко приносили дары, укрепляющие отношения со своим покровителем."}),(0,l.jsx)(n.p,{children:"С 1980 года Кайл возобновил активное сотрудничество со своим давним союзником Эрнестом Клайном, и в этом для него была уже своя выгода. При захвате преступников, наводку на которых давал Эрнест, Кайл конфисковывал все магические артефакты, которые они носили с собой. До этого артефакты переходили от одних преступников к другим, и Дикая Охота это не контролировала. Теперь же Кайл соорудил склад для артефактов в неприметном месте в горах, и каждый отнятый у преступника магический предмет отправлялся туда. Таковы были условия его договора с Хранителем: собирать конфискованные предметы и держать их на складе можно, использовать — нельзя."}),(0,l.jsx)(n.p,{children:"С 1986 года произошел всплеск активности самых разных религиозных культов. В эти годы начали действовать культисты самой разной степени агрессивности, были и культы, которые в те периоды только образовывались. Это были и культисты из южных подземелий, и сатанисты, и огнепоклонники — перечислять можно было долго. Выслеживанием этих культистов и занималась Дикая Охота. Лишь к концу 20 века борьба начала приносить свои результаты, но для этого Кайлу и его отряду пришлось соорудить множество распятий, прибивая к ним культистов, а некоторых отправить на костер подобно суду инквизиции. События с 1986 по 1999 года именуются в Дикой Охоте как Второй крестовый поход."}),(0,l.jsx)(n.p,{children:"В 1999 году в библиотеке произошли перемены — цилинь Амала Каур стала помощницей библиотекаря, и обязанности были поделены между ними. Тут же нашелся злоумышленник, который решил этим воспользоваться, и похитил одну из книг из запретной секции, которая была под надзором Амалы. Цилинь не растерялась и тут же обратилась за помощью к Дикой Охоте. Книжного вора нашли уже в 2004 году, преступник был отправлен в темницу с отрубленными пальцами, а книга была возвращена в библиотеку на законное место."}),(0,l.jsx)(n.p,{children:"Последующие годы Кайл продолжал искать призвание Дикой Охоты, советуясь со своими приближенными охотниками, а также с Всадниками. Вместе они решили начать новое, уже третье паломничество на территорию Зверя Греха, чтобы тот смог направить Дикую Охоту на их пути. Путешествие к Проклятому коню совершалось несколько раз в течение многих лет и завершилось к 2010 году."}),(0,l.jsx)(n.p,{children:"В 2011 году Кайл обратился к Хранителю, чтобы тот выковал ему легендарное оружие. С ним лидер Дикой Охоты начал помогать стражам в защите бастионов, избегая западного бастиона по причинам давних разногласий. Патрули охотников стали еще эффективнее. До сегодняшних дней Дикая Охота следит за порядком как в пределах бастионов, так и за стенами, исполняя свой нерушимый долг, и Кайл Блейк по-прежнему выходит со своими охотниками в патруль. С самого первого года он был лидером Дикой Охоты, и другой жизни он попросту не знает."})]})})]}),(0,l.jsxs)(r,{title:"Дополнительно",children:[(0,l.jsx)(r,{title:"Факты о персонаже",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Маскировка расы",children:(0,l.jsx)(n.p,{children:'Лидер Дикой Охоты причисляет себя к оммедзи, чтобы скрыть свою настоящую расу. Он представляется другим как маг, специализирующийся на зачаровании драгоценными камнями, а свой необычный раскрас называет "ликом смерти" - своей маской для ритуалов.'})}),(0,l.jsx)(h,{title:"День Памяти",children:(0,l.jsx)(n.p,{children:"После столкновения с Орденом, которое привело к смерти одного из призраков Дикой Охоты, хотя бы раз в году всю процессию охотников можно встретить у туманных болот, где они молча стоят у самого берега. Так называемый День Памяти был основан Кайлом и соблюдается каждый год по сей день."})}),(0,l.jsx)(h,{title:"Увлечение техникой",children:(0,l.jsx)(n.p,{children:"Кайл увлекается современной техникой, в особенности мотоциклами. Часто его можно увидеть в кожаной куртке и в мотоциклетном шлеме, который для лидера Дикой Охоты вообще является любимым атрибутом."})}),(0,l.jsx)(h,{title:"Современная культура",children:(0,l.jsx)(n.p,{children:"Кайл пытается разобраться и в современной культуре, например, чтобы понять, почему молодые грешники сравнивают его со скелетом из некой видеоигры. Услышав историю этого персонажа и то, на что он способен, Кайл согласился, что некоторая схожесть… присутствует, но использование имени персонажа в качестве прозвища ему не понравилось."})}),(0,l.jsx)(h,{title:"Толерантность",children:(0,l.jsx)(n.p,{children:"Кайл толерантен, но не в том смысле, что ненавидит всех одинаково, а в том, что спокойно относится к грешникам разных цветов кожи и считает их всех равными между собой."})}),(0,l.jsx)(h,{title:"Скрытие происхождения",children:(0,l.jsx)(n.p,{children:"Кайл очень старается скрыть свое латиноамериканское происхождение, выдавая себя за британца, и в присутствии испанцев переживает, что его настоящую этническую принадлежность раскроют."})}),(0,l.jsx)(h,{title:"Любимая книга",children:(0,l.jsx)(n.p,{children:'Трудно поверить, но Кайл Блейк читает книги. Самой его любимой является "Дон Кихот" — что уж говорить, в жизни Кайла тоже было немало сражений с ветряными мельницами, а потому он хорошо понимает героя романа Сервантеса. Своему коню он дал кличку Росинант, но больше никто, кроме него, об этом не знает.'})}),(0,l.jsx)(h,{title:"Чувства к Эриде Диас",children:(0,l.jsx)(n.p,{children:"Кайл испытывает влечение к Эриде Диас, однако из-за ее связи с Черным рынком не может относиться к ней иначе, как к врагу — ненависть Палача к преступному миру Энкража слишком сильна. И все же именно из-за этого чувства Кайла изредка посещают мысли о том, как все сложилось бы, будь у него другая судьба, при которой он стал бы не призраком Дикой Охоты, а кем-то еще."})})]})}),(0,l.jsx)(r,{title:"Внешность",children:(0,l.jsxs)(j,{children:[(0,l.jsx)(n.p,{children:"Чаще всего лицо Кайла выглядит мертвенно-бледным из-за нанесенного на него масляного грима. Для большего эффекта мужчина наносит черные полосы вокруг губ, которые напоминают шрамы, и таким же цветом обводит глаза. Из-за такого образа его янтарные глаза медного оттенка кажутся красными. Выходя в таком виде, грешник носит капор, закрывающий голову и шею, на которой нарисованы шейные позвонки, продолжающие раскрас на его лице. Также Кайл неизменно носит черный плащ длиной до колена и такого же цвета брюки с ботинками."}),(0,l.jsx)(n.p,{children:'В истинном облике все тело Кайла покрывают доспехи. Шлем лидера Дикой Охоты внешне напоминает череп с короной из шипов, металлические шипы также окаймляют его голову, ими же украшены наплечники и набедренники. По форме доспех от груди до ног напоминает анатомический скелет, плечи, локти, кисти, бедра и колени усилены дополнительными защитными пластинами. После принятия истинного облика внешность Кайла снова возвращается к обычной, раскрас пропадает, и тогда свое лицо грешник и вовсе закрывает мотоциклетным шлемом, с которым обычно носит кожарую куртку, джинсы и высокие ботинки, превращаясь в "беспечного ездока".'}),(0,l.jsx)(n.p,{children:"У Кайла черные прямые волосы до плеч, которые он укладывает назад, из-за чего хорошо заметны его угловатые черты лица. У него светлая кожа золотисто-персикового оттенка. Его рост — 186 см, вес — 79 кг, он крепко сложен и обладает внушительной комплекцией, которая выражается в широких плечах и груди, а также в хорошо развитой мускулатуре. Вместе с тем ноги у него длинные и вдобавок к этому еще и достаточно стройные."})]})}),(0,l.jsx)(r,{title:"Навыки и умения",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Владение холодным оружием",children:(0,l.jsx)(n.p,{children:"Превосходные навыки владения холодным оружием с коротким и средним клинком, хорошие навыки владения холодным оружием с длинным клинком."})}),(0,l.jsx)(h,{title:"Стрельба",children:(0,l.jsx)(n.p,{children:"Хорошие навыки стрельбы из револьвера, средние навыки стрельбы из пистолета."})}),(0,l.jsx)(h,{title:"Физическая подготовка",children:(0,l.jsx)(n.p,{children:"Хорошая физическая подготовка."})}),(0,l.jsx)(h,{title:"Верховая езда",children:(0,l.jsx)(n.p,{children:"Хорошие навыки верховой езды."})}),(0,l.jsx)(h,{title:"Плавание",children:(0,l.jsx)(n.p,{children:"Хорошие навыки плавания."})}),(0,l.jsx)(h,{title:"Наблюдательность",children:(0,l.jsx)(n.p,{children:"Острая наблюдательность."})})]})}),(0,l.jsx)(r,{title:"Слабости",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Отсутствие магии",children:(0,l.jsx)(n.p,{children:"У Кайла нет магических способностей, он может лишь наделять оружие магическими свойствами и усилять себя."})}),(0,l.jsx)(h,{title:"Слабые навыки допроса",children:(0,l.jsx)(n.p,{children:"Лидер Дикой Охоты обладает слабыми навыками допроса, ему проще получать информацию из окружающих объектов, чем от свидетеля или подозреваемого."})}),(0,l.jsx)(h,{title:"Потеря эмоциональной чувствительности",children:(0,l.jsx)(n.p,{children:"После снятия доспехов Кайл на время теряет эмоциональную чувствительность и способность к эмпатии."})}),(0,l.jsx)(h,{title:"Привязанность к бойцам",children:(0,l.jsx)(n.p,{children:"Лидер Дикой Охоты не может жертвовать своими бойцами, и даже когда победа практически у него в руках, он отступит, если жизнь охотника под угрозой."})}),(0,l.jsx)(h,{title:"Отношение к детям",children:(0,l.jsx)(n.p,{children:"Кайл не может причинить детям вред или подвергнуть их ситуации, в которой им будет причинен вред."})}),(0,l.jsx)(h,{title:"Узнаваемость гравировок",children:(0,l.jsx)(n.p,{children:"Гравировки Кайла хорошо узнаваемы, и их использование Дикой Охотой может указывать на причастность Кайла к охотникам."})})]})}),(0,l.jsx)(r,{title:"Связанные персонажи",children:(0,l.jsxs)(d,{children:[(0,l.jsx)(h,{title:"Мариано Рамирес де Ариас (Роберт Каннингем)",children:(0,l.jsx)(n.p,{children:"Людской мир. Дед Франсиско, ныне Роберт Каннингем, 29 лет. Связан с ним обещанием дать ему работу на изумрудном руднике. Связанный предмет — изумруд в форме восьмиугольника с усеченными углами массой 2.8 карата."})}),(0,l.jsx)(h,{title:"Долорес Руис Хименес (Рауль Антонио Хименес)",children:(0,l.jsx)(n.p,{children:"Людской мир. Цыганка из Картахены, ныне Рауль Антонио Хименес, 26 лет. Связана с Франсиско обещанием убить испанского капитана. Связанный предмет — цыганская игла длиной 17 см и диаметром 2 мм."})})]})})]}),(0,l.jsx)(x,{children:(0,l.jsx)(n.p,{children:"Мы носим в себе скрытого палача, нереализованного преступника. А те, у кого не хватает отваги открыто выразить свою наклонность к убийству, убивают в своих мечтах, наполняют трупами свои кошмары"})})]})}function s(e,l){throw Error("Expected "+(l?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}e.s(["default",0,function(e={}){let{wrapper:s}={...(0,i.useMDXComponents)(),...e.components};return s?(0,l.jsx)(s,{...e,children:(0,l.jsx)(n,{...e})}):n(e)}])}]);